-- Restaura os registros históricos que ainda existiam apenas em src/data/testes.json.
-- A consulta do dashboard e da Ficha passa a encontrar o histórico integral na
-- tabela única testes_afericoes. Todos estes registros são importações do Forms,
-- cuja planilha de 24 colunas não classifica CEDAE; portanto são AdR (ADR).
--
-- Importante: ON CONFLICT DO NOTHING preserva eventuais registros já existentes
-- no banco, inclusive testes criados manualmente. Os IDs do Forms são mantidos.

INSERT INTO public.testes_afericoes (
  id, hora_inicio, hora_conclusao, email, nome, data_teste, tipo_servico,
  elevatoria, grupo, tensao_v, corrente_a, retaguarda, recalque,
  corrente_shutoff, retaguarda_shutoff, recalque_shutoff, impossibilidade,
  servico_executado, nome_colaboradores, observacao, na_chegada, na_saida,
  status, tipo_teste, elevatoria_codigo, criado_por
)
SELECT
  r.id, r.hora_inicio, r.hora_conclusao, r.email, r.nome, r.data_teste,
  r.tipo_servico, r.elevatoria, r.grupo, r.tensao_v, r.corrente_a,
  r.retaguarda, r.recalque, r.corrente_shutoff, r.retaguarda_shutoff,
  r.recalque_shutoff, r.impossibilidade, r.servico_executado,
  r.nome_colaboradores, r.observacao, r.na_chegada, r.na_saida, r.status,
  'ADR', public.normalizar_codigo_elevatoria(r.elevatoria),
  'IMPORTACAO_PLANILHA'
FROM jsonb_to_recordset($historico_testes$
